package com.findback.app;

import android.Manifest;import android.app.Notification;import android.app.PendingIntent;import android.app.RemoteInput;import android.content.Context;import android.content.Intent;import android.content.IntentFilter;import android.content.pm.PackageManager;import android.location.Location;import android.location.LocationManager;import android.media.AudioManager;import android.media.ToneGenerator;import android.net.ConnectivityManager;import android.net.Network;import android.net.NetworkCapabilities;import android.os.Build;import android.os.Bundle;import android.os.CancellationSignal;import android.os.Handler;import android.os.Looper;import android.service.notification.NotificationListenerService;import android.service.notification.StatusBarNotification;
import java.text.DateFormat;import java.util.Date;import java.util.List;import java.util.concurrent.atomic.AtomicBoolean;

/** Notification-only WhatsApp command receiver; does not store the notification text. */
public class WhatsAppCommandListener extends NotificationListenerService {
    private static final String WA="com.whatsapp", WAB="com.whatsapp.w4b";private static final long TIMEOUT=12_000L;private final Handler handler=new Handler(Looper.getMainLooper());
    @Override public void onNotificationPosted(StatusBarNotification item){
        if(item==null||!RecoveryStore.armed(this)||!RecoveryStore.configured(this))return;String pkg=item.getPackageName();if(!WA.equals(pkg)&&!WAB.equals(pkg))return;
        Notification n=item.getNotification();Bundle e=n.extras;if(e==null||e.getBoolean(Notification.EXTRA_IS_GROUP_CONVERSATION,false))return;
        StringBuilder body=new StringBuilder();append(body,e.getCharSequence(Notification.EXTRA_TEXT));append(body,e.getCharSequence(Notification.EXTRA_BIG_TEXT));CharSequence[] lines=e.getCharSequenceArray(Notification.EXTRA_TEXT_LINES);if(lines!=null)for(CharSequence line:lines)append(body,line);
        String code=RecoveryStore.extract(body.toString());if(code==null||RecoveryStore.check(this,code)!=RecoveryStore.Check.OK)return;if(!RecoveryStore.allowReply(this))return;
        if(RecoveryStore.beep(this))beep();locateAndReply(n);
    }
    private void append(StringBuilder b,CharSequence v){if(v!=null)b.append('\n').append(v);}
    private void beep(){ToneGenerator tone=null;try{tone=new ToneGenerator(AudioManager.STREAM_ALARM,90);if(tone.startTone(ToneGenerator.TONE_PROP_BEEP,3200)){ToneGenerator keep=tone;handler.postDelayed(keep::release,3500);}}catch(RuntimeException ignored){if(tone!=null)tone.release();}}
    private void locateAndReply(Notification n){
        if(!hasLocation()){reply(n,"FindBack: location permission is missing. Enable it in FindBack settings.");return;}
        if(Build.VERSION.SDK_INT>=29&&checkSelfPermission(Manifest.permission.ACCESS_BACKGROUND_LOCATION)!=PackageManager.PERMISSION_GRANTED){reply(n,"FindBack: set location to Allow all the time before losing the phone.");return;}
        LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);if(lm==null){reply(n,"FindBack: Android location service is unavailable.");return;}
        if(Build.VERSION.SDK_INT<30){reply(n,format(bestLast(lm),true));return;}String provider=provider(lm);if(provider==null){reply(n,format(bestLast(lm),true));return;}
        AtomicBoolean done=new AtomicBoolean(false);CancellationSignal cancel=new CancellationSignal();Runnable timeout=()->{if(done.compareAndSet(false,true)){cancel.cancel();reply(n,format(bestLast(lm),true));}};handler.postDelayed(timeout,TIMEOUT);
        try{lm.getCurrentLocation(provider,cancel,getMainExecutor(),loc->{if(!done.compareAndSet(false,true))return;handler.removeCallbacks(timeout);reply(n,format(loc!=null?loc:bestLast(lm),loc==null));});}
        catch(SecurityException|IllegalArgumentException ex){if(done.compareAndSet(false,true)){handler.removeCallbacks(timeout);reply(n,format(bestLast(lm),true));}}
    }
    private boolean hasLocation(){return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
    private String provider(LocationManager lm){try{if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED&&lm.isProviderEnabled(LocationManager.GPS_PROVIDER))return LocationManager.GPS_PROVIDER;if(lm.isProviderEnabled(LocationManager.NETWORK_PROVIDER))return LocationManager.NETWORK_PROVIDER;}catch(SecurityException ignored){}return null;}
    private Location bestLast(LocationManager lm){try{Location best=null;List<String> providers=lm.getProviders(true);for(String p:providers){Location x=lm.getLastKnownLocation(p);if(x!=null&&(best==null||x.getTime()>best.getTime()))best=x;}return best;}catch(SecurityException|IllegalArgumentException ex){return null;}}
    private String format(Location loc,boolean cached){StringBuilder s=new StringBuilder("FindBack recovery reply\n");if(loc==null)s.append("Location: unavailable. Check Location and app permissions.\n");else{s.append("Map: https://maps.google.com/?q=").append(loc.getLatitude()).append(',').append(loc.getLongitude()).append('\n');long age=Math.max(0,System.currentTimeMillis()-loc.getTime());s.append("Updated: ").append(age(age));if(cached)s.append(" (last known)");s.append('\n');s.append("Accuracy: ").append(loc.hasAccuracy()?"about "+Math.round(loc.getAccuracy())+" m":"unavailable").append('\n');s.append("Location time: ").append(DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT).format(new Date(loc.getTime()))).append('\n');}s.append("Battery: ").append(battery()).append('\n').append("Network: ").append(network());return s.toString();}
    private String age(long ms){long m=ms/60_000;if(m<1)return "just now";if(m<60)return m+" minute(s) ago";long h=m/60;if(h<24)return h+" hour(s) ago";return (h/24)+" day(s) ago";}
    private String battery(){Intent i=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(i==null)return "unknown";int l=i.getIntExtra("level",-1),s=i.getIntExtra("scale",-1);return l<0||s<=0?"unknown":Math.round(l*100f/s)+"%";}
    private String network(){ConnectivityManager c=(ConnectivityManager)getSystemService(Context.CONNECTIVITY_SERVICE);if(c==null)return "unknown";try{Network n=c.getActiveNetwork();if(n==null)return "no connection";NetworkCapabilities x=c.getNetworkCapabilities(n);if(x==null||!x.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET))return "connected, no internet";return x.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?"Wi-Fi internet":x.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)?"mobile internet":"internet connected";}catch(SecurityException ex){return "unknown";}}
    private void reply(Notification n,String message){if(n.actions==null)return;for(Notification.Action a:n.actions){RemoteInput[] inputs=a.getRemoteInputs();if(inputs==null||inputs.length==0||a.actionIntent==null)continue;boolean free=false;Bundle results=new Bundle();for(RemoteInput i:inputs){free|=i.getAllowFreeFormInput();results.putCharSequence(i.getResultKey(),message);}if(!free)continue;Intent intent=new Intent();RemoteInput.addResultsToIntent(inputs,intent,results);try{a.actionIntent.send(this,0,intent);}catch(PendingIntent.CanceledException ignored){}return;}}
}
